import { useTheme } from '../../themes/ThemeContext';
import { HAS_BBS_RENDER, shipArtUrl } from './artCatalog';

/**
 * Ship, station and planet pixel art.
 * Cyber mode: full color gritty art.
 * BBS mode: the stardock and planets have dedicated green phosphor renders
 * (dithered, with scanlines). Ships use a green phosphor CRT filter on the
 * color art. Planet art is generated by tools/art/generate_planets.py.
 */

interface ShipArtProps {
  shipType: string;
  maxWidth?: number;
  alt?: string;
  caption?: string;
  compact?: boolean;
}

export default function ShipArt({ shipType, maxWidth = 480, alt, caption, compact }: ShipArtProps) {
  const { theme } = useTheme();
  const colorUrl = shipArtUrl(shipType);
  if (!colorUrl) return null;

  const isBbs = theme === 'bbs';
  const key = shipType.toLowerCase().replace(/\s+/g, '_');
  const bbsRender = isBbs && HAS_BBS_RENDER.has(key);
  const url = bbsRender ? colorUrl.replace(/\.webp$/, '_bbs.webp') : colorUrl;

  return (
    <div style={{ textAlign: 'center', padding: compact ? '4px 0' : '12px 0' }}>
      <img
        src={url}
        alt={alt || caption || shipType}
        loading="lazy"
        style={{
          maxWidth: `min(${maxWidth}px, 92vw)`,
          width: '100%',
          height: 'auto',
          borderRadius: isBbs ? 0 : '6px',
          border: isBbs ? '1px solid rgba(51,255,51,0.4)' : '1px solid rgba(0,255,255,0.25)',
          imageRendering: key.startsWith('planet_') || bbsRender ? 'pixelated' : 'auto',
          filter: isBbs && !bbsRender
            ? 'grayscale(1) sepia(1) hue-rotate(55deg) saturate(3) brightness(0.95) contrast(1.1)'
            : 'none',
          boxShadow: isBbs
            ? '0 0 18px rgba(51,255,51,0.25)'
            : '0 0 18px rgba(0,255,255,0.15)',
        }}
      />
      {caption && (
        <div style={{
          fontFamily: "'VT323', 'IBM Plex Mono', monospace",
          fontSize: '14px',
          marginTop: '4px',
          color: isBbs ? '#33ff33' : 'rgba(0,255,255,0.75)',
          letterSpacing: '1px',
        }}>
          {caption}
        </div>
      )}
    </div>
  );
}
